<script setup lang="ts">
const { data, refresh } = await useFetch<any>('/api/reviews')
const current=ref(0); const reveal=ref(false); const cards=computed(()=>data.value?.cards||[]); const card=computed(()=>cards.value[current.value]);
const next=async(rating:string)=>{if(!card.value)return;await $fetch('/api/reviews',{method:'POST',body:{card:card.value.card,rating}});reveal.value=false;current.value++;await refresh()}
</script>
<template><section><div class="page-title"><span class="eyebrow">REPETIÇÃO ESPAÇADA</span><h1>Revisar agora</h1><p class="muted">{{cards.length}} cartões pendentes · {{data?.totals?.accuracy ? Math.round(data.totals.accuracy*100):0}}% de acerto histórico.</p></div><div v-if="card" class="card" style="max-width:620px;text-align:center;padding:45px 25px"><span class="eyebrow">CARTÃO {{current+1}} DE {{cards.length}}</span><div class="hanzi" style="font-size:105px;margin:30px">{{card.card}}</div><div v-if="reveal"><h2>{{card.meaning}}</h2><p class="muted">{{card.pinyin}} · intervalo atual: {{card.interval_days}} dias</p><div class="grid" style="grid-template-columns:repeat(4,1fr);margin-top:30px"><button class="button" @click="next('again')">Errei</button><button class="button" @click="next('hard')">Difícil</button><button class="button primary" @click="next('good')">Bom</button><button class="button" @click="next('easy')">Fácil</button></div></div><button v-else class="button primary" @click="reveal=true">Mostrar resposta</button></div><div v-else class="card" style="max-width:620px;text-align:center;padding:45px"><div class="hanzi">✓</div><h2>Tudo revisado por hoje!</h2><p class="muted">As próximas revisões aparecerão automaticamente na data calculada.</p></div></section></template>
